import{_ as t,o,c as s,a0 as a}from"./chunks/framework.ChlVJx0I.js";const p=JSON.parse('{"title":"The skill tool loads referenced skills by name","description":"","frontmatter":{},"headers":[],"relativePath":"adr/0035-the-skill-tool-loads-referenced-skills-by-name.md","filePath":"adr/0035-the-skill-tool-loads-referenced-skills-by-name.md","lastUpdated":1792012601000}'),l={name:"adr/0035-the-skill-tool-loads-referenced-skills-by-name.md"};function i(n,e,r,d,h,c){return o(),s("div",null,[...e[0]||(e[0]=[a('<h1 id="the-skill-tool-loads-referenced-skills-by-name" tabindex="-1">The skill tool loads referenced skills by name <a class="header-anchor" href="#the-skill-tool-loads-referenced-skills-by-name" aria-label="Permalink to &quot;The skill tool loads referenced skills by name&quot;">​</a></h1><p>The shipped skills reference each other by name: <code>grill-with-docs</code> says &quot;call the Skill tool twice, for &#39;grilling&#39; and &#39;domain-modeling&#39;&quot;, and ten more skills in the tracked suite carry the same shape. The wording comes from the upstream&#39;s home environment, where a Skill tool exists. pi has no such tool: the model learns where a skill lives from the skills section of the system prompt, so a name reference makes it re-type the long install path by hand. In the session behind issue #143 (01a13a4d), the model guessed the wrong bucket (<code>engineering/grilling</code> instead of <code>productivity/grilling</code>) and a mangled directory name (<code>pi-extock</code>), and two reads died with ENOENT before the model recovered by finding the tree.</p><p>We decided: a small extension, skill-tool, registers one <code>skill</code> tool that takes a skill name and loads that skill. The name list is pi&#39;s own registry, captured from <code>before_agent_start</code>&#39;s <code>systemPromptOptions.skills</code> at every run, so the tool can only ever point at a skill pi loaded into the run, and a name pi does not know gets back the loaded names to correct against. The tool returns the same block shape pi&#39;s <code>/skill:</code> expansion records - the tag with name and location, the base-directory line, the body with the frontmatter stripped - so a name-based load and an explicit command land the model in the same place. The extension never scans the filesystem and never re-implements discovery: like skill-command, which normalizes input and lets pi own the expansion (ADR 0033), the tool only resolves a name against what pi already told the model.</p><h2 id="considered-options" tabindex="-1">Considered options <a class="header-anchor" href="#considered-options" aria-label="Permalink to &quot;Considered options&quot;">​</a></h2><ul><li><strong>Edit the vendored skill text to point at file paths.</strong> Rejected: the suite carries the cross-reference in eleven files, so the edits scatter across tracked upstream copies; repo-root-relative paths do not resolve in the &quot;references are relative to the skill directory&quot; context the injection declares; and the next skill sync merges every edit against upstream. The first draft of the fix for #144 did exactly this for one file and got all three of those wrong.</li><li><strong>Parse the rendered system prompt&#39;s <code>&lt;available_skills&gt;</code> section.</strong> Rejected: <code>before_agent_start</code> already hands the extension the typed <code>skills</code> array that section renders from. Parsing pi&#39;s text format would break on a pi change; trusting the typed list cannot.</li><li><strong>Scan the skill directories ourselves.</strong> Rejected: it duplicates pi&#39;s discovery and can disagree with it (name collisions, disabled skills, toggles). Capturing the registry keeps the tool pinned to what the model was actually told.</li><li><strong>Patch pi upstream to ship the tool.</strong> May happen; this extension closes the gap on the pi versions in use today, and if pi ships its own <code>skill</code> tool the name collision is the one thing to revisit.</li></ul><h2 id="consequences" tabindex="-1">Consequences <a class="header-anchor" href="#consequences" aria-label="Permalink to &quot;Consequences&quot;">​</a></h2><ul><li>Every install of the package gains one active tool - one prompt line, by design: the tool must be present for the model to follow a skill&#39;s instructions, so it cannot be a user-only tool.</li><li>The tool loads only skills pi loaded into the run. A name the model was never told about fails with the loaded list; a file that vanished after the run started (a <code>/reload</code> race) reports a reload hint instead of a bare ENOENT.</li><li><code>disable-model-invocation</code> skills stay out of the model&#39;s own selection; the tool loads one only if the model reaches for the name, as a user-invoked skill&#39;s instructions may direct.</li><li>The tool&#39;s result is byte-for-byte the shape of pi&#39;s expansion block, so a session that loaded a skill by name reads to the model like a session that commanded it. The tool normalizes a file&#39;s BOM and line endings the way pi does before it parses the frontmatter, so the comparison holds on a CRLF checkout, not only on an LF one.</li></ul>',7)])])}const k=t(l,[["render",i]]);export{p as __pageData,k as default};
